pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 hash) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 2 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number + 1)));
        vm.roll(block.number + 2);

        vm.prank(actor);
        bool settleOk = true;
        try c.settle() {
            settleOk = true;
        } catch {
            settleOk = false;
        }

        assertTrue(settleOk);
    }
}
